/// <summary>
/// MPJ-21310 DEVOPS 34618
/// Responsible for dealing with item substitution logic.
/// </summary>
class METSalesItemSubstitution
{        
    // TODO This needs to be integrated with the date-based reservation logic, 
    // which is still pending design/implementation.
    
    // TODO need to determine manual process for reservation and whether this will
    // be used/permitted.

    #define.MAXSUBLEVELS(10)    

    // Referenced records
    SalesLine                               salesLine;
    METSalesLine                            metSalesLine;
    InventDim                               inventDim;
    SalesTable                              salesTable;

    // Options
    boolean                                 interactive;  
    boolean                                 verboseLogging;
    boolean                                 runReservationTimeChecks;   // Checks at time of line reservation

    // State/member
    UserConnection                          verboseLogConnection;
    METSalesItemSubstitutionAccountRelation substitutionGroup;
    METSalesItemSubstitutionRounding        rounding;


}

Method.Source:
    /// <summary>
    /// Perform substitute checks/replacements.
    /// </summary>
    /// <returns>True if validation result is ok. (Not necessarily whether a replacement was made)</returns>
    public boolean run()
    {
        boolean ret = true;

        if(!CustParameters::find().METSubstitutionEnabled)
        {
            // Subs not enabled at legal-entity level.
            return true;
        }

        if(!salesLine.metSubstitutionsActive())
        {
            // Subs not applicable to this line.
            return true;
        }

        if(CustParameters::find().METSubstitutionVerboseLogging)
        {
            this.verboseLogging         = true;
            this.verboseLogConnection   = new UserConnection();

            if(!metSalesLine.SubstitutionVerboseLogReference)
            {
                metSalesLine.SubstitutionVerboseLogReference = newGuid();
            }
        }

        this.verboseInfo(funcName(), strFmt("@MET:SalesOrderLotIdRecId",
                                            salesLine.SalesId,
                                            salesLine.InventTransId,
                                            salesLine.RecId));

        this.verboseInfo(funcName(), strFmt("@MET:RequestedItemInventSiteQty",
                                            salesLine.ItemId, 
                                            salesTable.InventSiteId,
                                            salesLine.SalesQty,
                                            salesLine.SalesUnit));

        inventDim.InventSiteId = salesTable.InventSiteId;

        // *** tbd, may define a separate "substitution group". For now
        // we"re using the customer group.
        substitutionGroup = salesTable.custTable_CustAccount().CustGroup;
        
        this.verboseInfo(funcName(), strFmt("@MET:CustAccountGroup",
                                            salesLine.CustAccount,
                                            substitutionGroup));

        this.verboseInfo(funcName(), strFmt("@MET:runReservationTimeChecks",   this.runReservationTimeChecks));

        // ****************************

        METSalesItemSubstitutionParentChild matchingParentChild;
        METSalesItemSubstitute              matchingItemSub;
        date                                today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        boolean     continueSearch      = true;
        ItemId      currentSearchItemID = salesLine.ItemId;
        container   itemsSearched;
        int         searchDepth         = 0;
        int         maxSearchDepth      = min(CustParameters::find().METSalesSubstituteMaxLevels, #MAXSUBLEVELS);

        if(!maxSearchDepth)
        {
            maxSearchDepth = #MAXSUBLEVELS;
        }

        while(continueSearch)
        {
            this.verboseInfo(funcName(), strFmt("@MET:SearchingSubstitutes", currentSearchItemID));

            searchDepth++;
            if(conFind(itemsSearched, currentSearchItemID))
            {
                throw error(strFmt("@MET:SubstituteLoopEncountered",
                            con2Str(itemsSearched)));
            }
            itemsSearched += currentSearchItemID;
            
            if(searchDepth > maxSearchDepth)
            {
                throw error(strFmt("@MET:MaxSearchDepthExceeded",
                            maxSearchDepth,
                            con2Str(itemsSearched)));
            }

            METSalesItemSubstitutionParentChild parentChild = this.searchParentChild(currentSearchItemID);
            
            if(parentChild)
            {
                this.verboseInfo(funcName(), strFmt("@MET:ParentChildFound", parentChild.description()));
                    
                currentSearchItemID = parentChild.ParentItemID;
                matchingParentChild = parentChild;
                matchingItemSub     = null;
            }
            else
            {
                this.verboseInfo(funcName(), strfmt("@MET:NoParentChildRelationshipFoundChildItem", currentSearchItemID));
                
                METSalesItemSubstitute itemSub;
                if(true)
                {
                    select firstonly validtimestate(today) itemSub
                        order by AccountCode asc
                        where   itemSub.ItemId              == currentSearchItemID
                        &&     (itemSub.InventSiteId == METConstants::emptyString || itemSub.InventSiteId == salesTable.InventSiteId)
                        &&     (itemSub.SubstitutionCode    == METSalesItemSubstitutionCode::Always
                            ||  itemSub.SubstitutionCode    == METSalesItemSubstitutionCode::Never)
                        &&  (   // table/group/all match
                            (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                                itemSub.AccountRelation == salesTable.CustAccount)
                        ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                                itemSub.AccountRelation == substitutionGroup)
                        ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                                itemSub.AccountRelation == METConstants::emptyString)
                        );
                
                    if(itemSub)
                    {
                        this.verboseInfo(funcName(), strFmt("@MET:SubstitutionFound", itemSub.description()));

                        currentSearchItemID     = itemSub.SubstituteItemID;
                        matchingItemSub         = itemSub;
                        matchingParentChild     = null;
                    }
                    else
                    {
                        this.verboseInfo(funcName(), "@MET:NoAlwaysNeverSubstitutionFound");
                    }
                }
                       
                if(!itemSub && this.runReservationTimeChecks)
                {
                    this.verboseInfo(funcName(), "@MET:SearchingReservationTimeSubstitutes", searchDepth == 1);
                    
                    select firstonly validtimestate(today) itemSub
                        order by AccountCode asc
                        where   itemSub.ItemId              == currentSearchItemID
                        &&      (itemSub.InventSiteId == METConstants::emptyString || itemSub.InventSiteId == salesTable.InventSiteId)
                        &&      itemSub.SubstitutionCode    != METSalesItemSubstitutionCode::Always
                        &&      itemSub.SubstitutionCode    != METSalesItemSubstitutionCode::Never
                        &&  (   // table/group/all match
                            (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                                itemSub.AccountRelation == salesTable.CustAccount)
                        ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                                itemSub.AccountRelation == substitutionGroup)
                        ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                                itemSub.AccountRelation == METConstants::emptyString)
                        );

                    if(itemSub)
                    {
                        this.verboseInfo(funcName(), strFmt("@MET:SubstituteFound", itemSub.description()));

                        matchingParentChild = null;
                            
                        switch(itemSub.SubstitutionCode)
                        {
                            case METSalesItemSubstitutionCode::Replacement:
                                matchingItemSub = itemSub;
                                break;
                            case METSalesItemSubstitutionCode::NoAlternative:
                                continueSearch  = false;
                                matchingItemSub = itemSub;
                                break;
                            case METSalesItemSubstitutionCode::OutOfStock:
                                Qty         qtyOnHand                   = this.queryOnHandQty(currentSearchItemID, inventDim);
                                boolean     itemHasSufficientQtyOnHand  = qtyOnHand >= salesLine.QtyOrdered;

                                this.verboseInfo(funcName(), strFmt("@MET:ItemOnhand",
                                                currentSearchItemID,
                                                qtyOnHand,
                                                itemHasSufficientQtyOnHand ? "@MET:SufficientOrderQuantity" : "@MET:InsufficientOderQuantity"));

                                if(itemHasSufficientQtyOnHand)
                                {
                                    // Out of stock entry found, but item has enough stock.
                                    this.verboseInfo(funcName(), "@MET:OutOfStockEntryFoundCurrentSearchItemEnoughStockFinishSearch");
                                    continueSearch = false;
                                }
                                else
                                {
                                    // Out of stock entry found, and search item is out of stock. Continue search.
                                    this.verboseInfo(funcName(), "@MET:OutOfStockEntryFoundCurrentSearchItemOutOfStock");
                                    currentSearchItemID = itemSub.SubstituteItemId;
                                    matchingItemSub     = itemSub;
                                }

                                break;
                            default:
                                throw error(strFmt("@MET:SubInvalidSubstitutionCode",
                                            itemSub.SubstitutionCode,
                                            funcName()));
                        }
                    }
                    else
                    {
                        this.verboseInfo(funcName(), strFmt("@MET:NoReservationTimeSubstituteFoundItem",
                                        currentSearchItemID));
                    }
                } 
                if(!itemSub)
                {
                    continueSearch = false;
                }
            }            
        }   // main search loop

        ttsbegin;
        
        boolean performUpdates = true;

        if(matchingItemSub || matchingParentChild)
        {
            boolean replaceItem = true;
            
            if(matchingItemSub)
            {
                this.verboseInfo(funcName(), strFmt("@MET:FinalMatchingSubstitute", matchingItemSub.description()));

                if(matchingItemSub.SubstitutionCode == METSalesItemSubstitutionCode::Always)
                {
                    performUpdates = this.yesNoPrompt(strFmt("@MET:SubPromptReplacement",
                                                    salesLine.ItemId, 
                                                    matchingItemSub.SubstituteItemId));
                }

                if(performUpdates)
                {
                    if(!metSalesLine.SubstituteOriginalItemID)
                    {
                        metSalesLine.SubstituteOriginalItemID       = salesLine.ItemId;
                    }
                    metSalesLine.SubstituteReplacementItemID    = matchingItemSub.SubstituteItemId;
                    metSalesLine.SubstituteParentItemID         = METConstants::emptyString;
                    metSalesLine.SubstitutionType               = METSalesItemSubstitutionType::SubstitutionCode;
                    metSalesLine.SubstitutionCode               = matchingItemSub.SubstitutionCode;
                    metSalesLine.SubstitutionSetupRefRecID      = matchingItemSub.RecId;
                    rounding                                    = matchingItemSub.Rounding;

                    switch(metSalesLine.SubstitutionCode)
                    {
                        case METSalesItemSubstitutionCode::Never:
                        case METSalesItemSubstitutionCode::NoAlternative:
                            replaceItem = false;
                            break;
                    }
                }
            }
            else
            {
                this.verboseInfo(funcName(), "@MET:NoMatchingSubstituteEntryFound");

                if(matchingParentChild)
                {
                    this.verboseInfo(funcName(), strFmt("@MET:FinalMatchingParentItem", matchingParentChild.description()));

                    if(matchingItemSub.SubstitutionCode == METSalesItemSubstitutionCode::Always)
                    {
                        performUpdates = this.yesNoPrompt(strFmt("@MET:SubPromptReplacementParentChild",
                                                                salesLine.ItemId,
                                                                matchingParentChild.ParentItemID));
                    }
                    
                    if(performUpdates)
                    {
                        if(!metSalesLine.SubstituteOriginalItemID)
                        {
                            metSalesLine.SubstituteOriginalItemID       = salesLine.ItemId;
                        }
                        metSalesLine.SubstituteReplacementItemID    = matchingParentChild.ParentItemID;
                        metSalesLine.SubstituteParentItemID         = matchingParentChild.ParentItemID;
                        metSalesLine.SubstitutionType               = METSalesItemSubstitutionType::ParentChild;
                        metSalesLine.SubstitutionCode               = METSalesItemSubstitutionCode::None;
                        metSalesLine.SubstitutionSetupRefRecID      = matchingParentChild.RecId;
                        rounding                                    = matchingParentChild.Rounding;
                    }
                }
            }

            if(performUpdates && metSalesLine.SubstituteReplacementItemID != salesLine.ItemId)
            {
                if(replaceItem)
                {
                    boolean copiedToNewLine;
                    if(salesLine.RecId)
                    {
                        this.copyToNewLine(metSalesLine.SubstituteReplacementItemID);
                        copiedToNewLine = true;
                    }
                    else
                    {
                        this.verboseInfo(funcName(), strFmt("@MET:ItemReplacedWith",
                                                            salesLine.ItemId,
                                                            metSalesLine.SubstituteReplacementItemID));                    
                    }

                    if(!copiedToNewLine)
                    {
                        salesLine.ItemId = metSalesLine.SubstituteReplacementItemID;
                        salesLine.itemIdChanged();
                        this.updateQuantity();

                        if(salesLine.RecId)
                        {
                            salesLine.metPackMETSalesLine(metSalesLine);
                            salesLine.update();
                            
                        }
                    }

                    info(strFmt("@MET:SubItemReplaced",
                        metSalesLine.SubstituteOriginalItemID,
                        metSalesLine.SubstituteReplacementItemID));
                }
            }
            if(!performUpdates)
            {
                this.verboseInfo(funcName(), "@MET:NoUpdatesMadePerformUpdatesFalseReturnFailed");
                ret = checkFailed("@MET:SubReplacementNotAccepted");
            }
        }
        else
        {
            this.verboseInfo(funcName(), "@MET:NoMatchingSubstituteParentChildRecordFoundNoSubstituteMade");
        }

        ttscommit;
        
        return ret;
    }

    /// <summary>
    /// Search for parent/child relationship.
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <returns>Matching record or null</returns>
    protected METSalesItemSubstitutionParentChild searchParentChild(ItemId _itemID)
    {
        METSalesItemSubstitutionParentChild parentChild;        
        select firstonly parentChild
            where   (parentChild.InventSiteId == METConstants::emptyString || parentChild.InventSiteId == salesTable.InventSiteId)
            &&      parentChild.ChildItemID     == _itemID;

        if(parentChild)
        {
            this.verboseInfo(funcName(), strFmt("@MET:ParentChildRelationshipExistsChildItemParentItem",
                                                parentChild.ChildItemID,
                                                parentChild.ParentItemID));

            return parentChild;
        }
        else
        {
            this.verboseInfo(funcName(), strFmt("@MET:ParentChildRelationshipDoesNotExistChildItem",
                                                _itemID));
        }
        return null;
    }

    /// <summary>
    /// Copy sales line to new line with specified item id.
    /// </summary>
    /// <param name = "_newItemId">_newItemId</param>
    /// <returns>New sales order line</returns>
    protected SalesLine copyToNewLine(ItemId _newItemId)
    {
        this.verboseInfo(funcName(), strFmt("@MET:CopyingNewLineWithItem",
                                            _newItemId));

        SalesLine newLine;

        this.updateQuantity();

        newLine.initFromSalesTable(salesTable);
        newLine.initFromSalesLine(salesLine, true, true, true);
        newLine.ItemId = _newItemId;        
        newLine.itemIdChanged();

        METSalesLine metNewLine = newLine.metSalesLine();
        metNewLine = metSalesLine.data();

        metNewLine.SalesLine = newLine.RecId;
        
        newLine.metPackMETSalesLine(metNewLine);
        newLine.insert();

        // TODO copy notes etc.
        

        guid logReference;
        metSalesLine.SubstitutionVerboseLogReference = logReference;    // clear ref on original record. 

        //Instead of directly updating the METSalesLine record, follow SysExtensionSerialization to perform update from base table
        SalesLine salesLineLoc = SalesLine::findRecId(metSalesLine.SalesLine, true);
        salesLineLoc.metPackMETSalesLine(metSalesLine);
        salesLineLoc.update();
        
        this.verboseInfo(funcName(), strFmt("@MET:OrderLineItemLotCopiedReplacedItemLot",
                                            salesLine.ItemId,
                                            salesLine.InventTransId,
                                            newLine.ItemId,
                                            newLine.InventTransId));
        
        salesLine.delete();   

        salesLine       = newLine;
        inventDim       = salesLine.inventDim();
        metSalesLine    = metNewLine;

        return newLine;
    }

    /// <summary>
    /// Find on-hand quantity for specified item
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>On-hand quantity</returns>
    protected Qty queryOnHandQty(ItemId _itemID, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(inventDim);
        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
        Qty             onHandQty;
        boolean         checkTestOnHandQtyTable = true; // **** This is temporary, for testing/debugging only
        
        // ***** This is only for testing!
        if(checkTestOnHandQtyTable)
        {
            METSalesItemSubstituteTestOnHand testOnHand = METSalesItemSubstituteTestOnHand::find(
                _inventDim.InventSiteId, 
                _itemID);
            if(testOnHand)
            {
                str msg = strFmt("@MET:UsingTestingOnhandQty",
                                testOnHand.QtyOnHand,
                                _itemID,
                                _inventDim.InventSiteId);
                this.verboseInfo(funcName(), msg);
                warning(msg);

                return testOnHand.QtyOnHand;
            }
        }

        if(CustParameters::find().METSubstitutionIncludeOnOrderInventory)
        {
            onHandQty = onHand.availOrdered(true);
            this.verboseInfo(funcName(), strFmt("@MET:OnhandQtyIncludingOnOrder",
                onHandQty));
        }
        else
        {
            onHandQty = onHand.availPhysical();
            this.verboseInfo(funcName(), strFmt("@MET:OnhandQtyPhysicalOnly",
                onHandQty));
        }
        return onHandQty;
    }

    /// <summary>
    /// Check and update quantity/unit if required.
    /// </summary>
    /// <returns>Validation result</returns>
    protected boolean updateQuantity()
    {
        boolean             ret                     = true;
        InventTable         originalItem            = InventTable::find(metSalesLine.SubstituteOriginalItemID);
        InventTableModule   originalItemInvent      = originalItem.inventTableModuleInvent();
        InventTable         replacementItem         = InventTable::find(metSalesLine.SubstituteReplacementItemID);
        InventTableModule   replacementItemInvent   = replacementItem.inventTableModuleInvent();    
        UnitOfMeasureSymbol replacementSalesUnit    = this.getItemSalesUnit(replacementItem.ItemId);
        
        this.verboseInfo(funcName(), "@MET:UpdatingQuantitySubstitutedItem");

        this.verboseInfo(funcName(), strFmt("@MET:OriginalItemOrdered",
                                            originalItem.ItemId,
                                            salesLine.SalesQty,
                                            salesLine.SalesUnit,
                                            salesLine.QtyOrdered,
                                            originalItemInvent.UnitId));

        this.verboseInfo(funcName(), strFmt("@MET:ReplacementItemInventoryUnitSalesUnit",
            replacementItem.ItemId,
            replacementItemInvent.UnitId,
            replacementSalesUnit));

        if(originalItemInvent.UnitId == replacementItemInvent.UnitID)
        {
            Qty replacementQtySalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                replacementItem.ItemId,
                InventDim::findOrCreate(inventDim).inventDimId,
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId,
                replacementSalesUnit,
                true,
                false);

            this.verboseInfo(funcName(), strFmt("@MET:ConversionFromInventoryUnitSalesUnit",
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId,
                replacementQtySalesUnit,
                replacementSalesUnit));

            if(real2int(replacementQtySalesUnit) != replacementQtySalesUnit)
            {                
                Qty     roundedSalesQty;
                boolean roundingApplied;
                int     roundingPrecision = 1;  // ** config?
                switch(rounding)
                {
                    case METSalesItemSubstitutionRounding::ToNearest:
                        roundedSalesQty = round(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                    case METSalesItemSubstitutionRounding::Up:
                        roundedSalesQty = roundUp(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                    case METSalesItemSubstitutionRounding::Down:
                        roundedSalesQty = roundDown(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                }
                if(roundingApplied)
                {
                    this.verboseInfo(funcName(), strFmt("@MET:RoundedUsingMethod",
                                                        replacementQtySalesUnit,
                                                        roundedSalesQty,
                                                        rounding));
                    replacementQtySalesUnit = roundedSalesQty;
                }
                else
                {
                    this.verboseInfo(funcName(), "@MET:NoRoundingAppliedDueConfiguration");
                    
                    if(replacementQtySalesUnit < 1)
                    {
                        this.warning(strFmt("@MET:SubUnitConversionWarning",
                                    salesLine.SalesQty,
                                    salesLine.SalesUnit,
                                    replacementQtySalesUnit,
                                    replacementSalesUnit,
                                    replacementItem.ItemId));  
                        
                        replacementQtySalesUnit = 1;    // *** TODO confirm requirements for this scenario.
                    }
                }
            }
            else
            {
                this.verboseInfo(funcName(), "@MET:RoundingNotRequired");
            }

            salesLine.SalesQty  = replacementQtySalesUnit;
            salesLine.SalesUnit = replacementSalesUnit;                
        
            // TODO min/max/etc is not working correctly with the site/item specific
            // settings mod. When it is, logic should not be replicated here. Ordinarily
            // it will be called via modifySalesQty below.
            this.applyMinMaxMultiple();

            salesLine.METSkipMinMaxMultipleCheck = true;
            SalesLine::modifySalesQty(
                salesLine, 
                inventDim, 
                true, 
                false);
            salesLine.METSkipMinMaxMultipleCheck = false;

            this.verboseInfo(funcName(), strFmt("@MET:FinalConversionSalesInventoryItem",
                salesLine.SalesQty,
                salesLine.SalesUnit,
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId,
                salesLine.ItemId));            
        }
        else
        {
            // How to handle this scenario? (Item A and B don"t have common inventory unit). Attempt conversion? Pending test scenarios.
            this.verboseInfo(funcName(), strFmt("@MET:ItemHaveDifferentInventoryUnitsUnableConvert",
                                                originalItem.ItemId,
                                                replacementItem.ItemId,
                                                originalItemInvent.UnitId,
                                                replacementItemInvent.UnitId));
            ret = false;
        }
        return ret;       
    }

/// <summary>
/// Apply min/max/multiple logic to sales order line. 
/// TODO, pending completion of site-specific sales unit mod.
/// </summary>
protected void applyMinMaxMultiple()
{
    InventItemSalesSetup salesSetup = this.findInventItemSalesSetup(salesLine.ItemId);
    if(salesSetup)
    {            
        this.verboseInfo(funcName(), strFmt("@MET:ItemSiteSetupFoundItemSite",
                                            salesLine.ItemId,
                                            salesSetup.inventSiteId()));
        if(salesSetup.LowestQty && salesLine.SalesQty < salesSetup.LowestQty)
        {
            this.verboseInfo(funcName(), strFmt("@MET:QuantityUpdatedMinimum", salesSetup.LowestQty));
            salesLine.SalesQty = salesSetup.LowestQty;
        }
        if(salesSetup.HighestQty && salesLine.SalesQty > salesSetup.HighestQty)
        {
            this.verboseInfo(funcName(), strFmt("@MET:QuantityUpdatedMaximum", salesSetup.highestQty));
            salesLine.SalesQty = salesSetup.HighestQty;
        }
        if(salesSetup.MultipleQty)
        {
            int salesQtyInt = real2int(salesLine.SalesQty);
            int multQtyInt  = real2int(salesSetup.MultipleQty);
            if(salesQtyInt mod multQtyInt)
            {
                this.verboseInfo(funcName(), strFmt("@MET:RoundingUpNearestMultiple",
                                                    salesLine.SalesQty,
                                                    multQtyInt));
                salesQtyInt         = ((salesQtyInt / multQtyInt) + 1) * multQtyInt;
                salesLine.SalesQty  = salesQtyInt;
            }
        }
    }
}

/// <summary>
/// Find sales unit for specified item.
/// </summary>
/// <param name = "_itemID">_itemID</param>
/// <returns>Sales unit</returns>
protected UnitOfMeasureSymbol getItemSalesUnit(ItemId _itemID)
{
    InventItemSalesSetup salesSetup = this.findInventItemSalesSetup(_itemID);
    if(salesSetup && salesSetup.METSalesUnit)
    {
        this.verboseInfo(funcName(), strFmt("@MET:SiteSpecificSalesUnitFoundItem",
                                    _itemID,
                                    salesTable.InventSiteId));
        return salesSetup.METSalesUnit;
    }
    this.verboseInfo(funcName(), strFmt("@MET:NoSiteSpecificSalesUnitFoundItem",
                                    _itemID,
                                    salesTable.InventSiteId));
    return InventTableModule::find(_itemID, ModuleInventPurchSales::Sales).UnitId; 
}

/// <summary>
/// Find site/item specific settings.
/// </summary>
/// <param name = "_itemID">_itemID</param>
/// <returns>InventItemSalesSetup</returns>
protected InventItemSalesSetup findInventItemSalesSetup(ItemId _itemID)
{
    InventDim siteDim;
    siteDim.InventSiteID    = this.salesTable.InventSiteId;
    siteDim                 = InventDim::findOrCreate(siteDim);
    InventItemSalesSetup salesSetup = InventItemSalesSetup::find(
        _itemID,
        siteDim.inventDimId);
    if(!salesSetup)
    {
        salesSetup = InventItemSalesSetup::findDefault(_itemID);                
    }
    return salesSetup;
}

private boolean warning(str _msg)
{
    this.verboseInfo(funcName(), _msg);
    return checkFailed(_msg);
}

    /// <summary>jh
    /// Add verbose info to the log.
    /// </summary>
    /// <param name = "_func">_func</param>
    /// <param name = "_msg">_msg</param>
    /// <param name = "_condition">_condition</param>
    private void verboseInfo(str _func, str _msg, boolean _condition = true)
    {
        if(this.verboseLogging && _condition)
        {
            METSalesItemSubstitutionVerboseLog  verboseLog;

            verboseLog.SalesId          = salesTable.SalesId;
            verboseLog.Message          = _msg;
            verboseLog.Function         = subStr(_func, strFind(_func, ".", 1, 999) + 1, 999);
            verboseLog.LogReference     = metSalesLine.SubstitutionVerboseLogReference;

            if(this.verboseLogConnection)
            {
                verboseLog.setConnection(this.verboseLogConnection);
            }
            verboseLog.insert();            
        }
    }

/// <summary>
/// Prompt message with yes/no confirmation. If non-interactive, assume a "Yes"
/// response. (eg via backend service/batch).
/// </summary>
/// <param name = "_msg">_msg</param>
/// <returns>Result</returns>
protected boolean yesNoPrompt(str _msg)
{
    if(interactive)
    {
        boolean promptRet = (Box::yesNo(_msg, DialogButton::No) == DialogButton::Yes);
        this.verboseInfo(funcName(), strFmt("@MET:Prompt",
                                            _msg,
                                            promptRet ? "@MET:UserConfirmedReplacement" : "@MET:UserCancelledReplacement"));
        return promptRet;
    }
    else
    {
        this.verboseInfo(funcName(), "@MET:ReplacementAcceptedWithoutPrompt");
        return true;
    }
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <param name = "_inventDim">_inventDim</param>
protected void new(
    SalesLine       _salesLine,
    METSalesLine    _metSalesLine,
    InventDim       _inventDim)
{
    salesLine       = _salesLine;
    metSalesLine    = _metSalesLine;
    inventDim       = _inventDim;
    salesTable      = salesLine.salesTable();
}

/// <summary>
/// Run substitute checks from UI.
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <param name = "_inventDim">_inventDim</param>
/// <returns>Validation result</returns>
static public boolean runSalesLineCreationFromForm(
    SalesLine       _salesLine,
    METSalesLine    _metSalesLine,
    InventDim       _inventDim)
{
    if(_metSalesLine.SubstituteOriginalItemID == METConstants::emptyString)
    {
        var sub = METSalesItemSubstitution::construct(
            _salesLine,
            _metSalesLine,
            _inventDim);
        sub.interactive                 = true;
        sub.runReservationTimeChecks    = (_salesLine.Reservation == ItemReservation::Automatic);
        return sub.run();
    }
    return true;
}

/// <summary>
/// Construct and init instance for use with reservation-time sub check.
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <param name = "_inventDim">_inventDim</param>
/// <returns>Instance</returns>
static public METSalesItemSubstitution constructForReservation(
    SalesLine       _salesLine,
    METSalesLine    _metSalesLine,
    InventDim       _inventDim)
{
    var sub = METSalesItemSubstitution::construct(
        _salesLine,
        _metSalesLine,
        _inventDim);
    sub.runReservationTimeChecks    = true;
    sub.interactive                 = true;
    return sub;
}

/// <summary>
/// construct
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <param name = "_inventDim">_inventDim</param>
/// <returns>New instance</returns>
static private METSalesItemSubstitution construct(
    SalesLine                               _salesLine,
    METSalesLine                            _metSalesLine,
    InventDim                               _inventDim)
{
    METSalesItemSubstitution sub = new METSalesItemSubstitution(
        _salesLine,
        _metSalesLine,
        _inventDim);
    return sub;
}

/// <summary>
/// Max. search depth. This is configurable in the inventory parameters but may
/// not exceed this number.
/// </summary>
/// <returns>Result</returns>
static public int maxSearchDepth()
{
    return #MAXSUBLEVELS;
}
